ON CONFLICT (local_date) DO NOTHING;
  GET DIAGNOSTICS written = ROW_COUNT;
  IF written <> 365 THEN
    RAISE EXCEPTION 'expected 365 new affirmations, got %', written;
  END IF;
END
$explore_affirmations$;
